// Prepare search parameters for MLS/Zillow API
const leads = $input.all();
const searchRequests = [];

for (const item of leads) {
  const lead = item.json;

  // Extract budget (handle various formats)
  let minPrice = 0;
  let maxPrice = 999999999;

  if (lead.Budget) {
    const budgetStr = String(lead.Budget).replace(/[^\d-]/g, '');

    // Handle range (e.g., "200000-300000")
    if (budgetStr.includes('-')) {
      const [min, max] = budgetStr.split('-').map(Number);
      minPrice = min || 0;
      maxPrice = max || 999999999;
    } else {
      // Single number - add ±10% buffer
      const budget = Number(budgetStr);
      if (budget > 0) {
        minPrice = Math.floor(budget * 0.9);
        maxPrice = Math.ceil(budget * 1.1);
      }
    }
  }

  // Extract bedrooms/bathrooms from priorities
  let minBedrooms = 0;
  let minBathrooms = 0;

  if (lead.Priorities) {
    const bedsMatch = lead.Priorities.match(/(\d+)\s*(?:bed|br|bedroom)/i);
    const bathsMatch = lead.Priorities.match(/(\d+)\s*(?:bath|ba|bathroom)/i);

    minBedrooms = bedsMatch ? parseInt(bedsMatch[1]) : 0;
    minBathrooms = bathsMatch ? parseInt(bathsMatch[1]) : 0;
  }

  // Extract location/zip codes from priorities
  const locationMatch = lead.Priorities?.match(/\b\d{5}\b/); // ZIP code
  const location = locationMatch ? locationMatch[0] : '';

  searchRequests.push({
    json: {
      leadName: lead.Name,
      leadEmail: lead.Email,
      leadPhone: lead.Phone,
      leadRowId: lead.rowNumber || lead['Row ID'],
      searchParams: {
        minPrice,
        maxPrice,
        minBedrooms,
        minBathrooms,
        propertyType: lead['Property Type'] || 'any',
        location: location || 'any',
        status: 'active',
        daysListed: 30 // Only properties listed in last 30 days
      },
      leadPreferences: {
        budget: lead.Budget,
        priorities: lead.Priorities,
        timeline: lead.Timeline
      }
    }
  });
}

return searchRequests;

// Process and rank property results
const searchData = $('Prepare MLS Search Parameters').item.json;
const properties = $input.item.json.value || $input.item.json; // Handle MLS or Zillow format

if (!properties || properties.length === 0) {
  return [{ json: { noResults: true, leadData: searchData } }];
}

// Normalize property data (MLS vs Zillow formats differ)
const normalizedProperties = properties.slice(0, 8).map(prop => {
  // MLS format
  if (prop.ListingId) {
    return {
      id: prop.ListingId || prop.ListingKey,
      price: prop.ListPrice,
      address: prop.UnparsedAddress,
      city: prop.City,
      state: prop.StateOrProvince,
      zip: prop.PostalCode,
      bedrooms: prop.BedroomsTotal,
      bathrooms: prop.BathroomsTotalInteger,
      sqft: prop.LivingArea,
      propertyType: prop.PropertyType,
      imageUrl: prop.Media?.[0]?.MediaURL || '',
      listingUrl: `https://www.realtor.com/realestateandhomes-detail/${prop.ListingKey}`,
      daysOnMarket: prop.DaysOnMarket || 'N/A'
    };
  }
  // Zillow format
  else {
    return {
      id: prop.zpid,
      price: prop.price,
      address: prop.address?.streetAddress,
      city: prop.address?.city,
      state: prop.address?.state,
      zip: prop.address?.zipcode,
      bedrooms: prop.bedrooms,
      bathrooms: prop.bathrooms,
      sqft: prop.livingArea,
      propertyType: prop.homeType,
      imageUrl: prop.imgSrc || prop.photos?.[0] || '',
      listingUrl: prop.detailUrl,
      daysOnMarket: prop.daysOnZillow || 'N/A'
    };
  }
});

return [{
  json: {
    leadData: searchData,
    properties: normalizedProperties,
    totalFound: normalizedProperties.length
  }
}];
